package dashboard.enterprise.agent.llm.registry;import dashboard.enterprise.agent.llm.provider.LlmProvider;import java.util.*;public final class InMemoryLlmProviderRegistry implements LlmProviderRegistry{private final Map<String,LlmProvider> providers=new LinkedHashMap<>();public void register(LlmProvider p){if(p==null)throw new IllegalArgumentException("Provider is required.");if(providers.putIfAbsent(p.providerId(),p)!=null)throw new IllegalArgumentException("Duplicate provider: "+p.providerId());}public LlmProvider require(String id){LlmProvider p=providers.get(id);if(p==null)throw new IllegalArgumentException("Unknown LLM provider: "+id);return p;}public Collection<LlmProvider> all(){return List.copyOf(providers.values());}}
